/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var dgemm = require( '@stdlib/blas/base/dgemm' ).ndarray;
var base = require( './../lib/base.js' );
var depth = require( './../lib/depth.js' );
var firstDifference = require( './fixtures/first_difference.js' );


// VARIABLES //

var SEED = 20261033;
var N = 37; // with a cutoff of 3: 37 → 18 → 9 → 4 (four levels, including peeling)
var CUTOFF = 3;
var LEVELS = 100;


// FUNCTIONS //

/**
* Returns the transpose operation used by `dgemm` for a real-valued matrix.
*
* @private
* @param {string} op - transpose operation
* @returns {string} equivalent operation
*/
function realOp( op ) {
	return ( op === 'no-transpose' ) ? 'no-transpose' : 'transpose';
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof base, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function treats `conjugate-transpose` as `transpose` on the recursive path', function test( t ) {
	var betas;
	var randi;
	var ops;
	var ref;
	var out;
	var A;
	var B;
	var C;
	var i;
	var j;

	randi = discreteUniform.factory({
		'seed': SEED
	});
	A = new Float64Array( N*N );
	B = new Float64Array( N*N );
	C = new Float64Array( N*N );
	for ( i = 0; i < N*N; i++ ) {
		A[ i ] = randi( -6, 6 );
		B[ i ] = randi( -6, 6 );
		C[ i ] = randi( -6, 6 );
	}
	ops = [
		[ 'conjugate-transpose', 'no-transpose' ],
		[ 'no-transpose', 'conjugate-transpose' ],
		[ 'conjugate-transpose', 'conjugate-transpose' ]
	];
	betas = [ 0.0, 2.0 ];
	t.strictEqual( depth( N, N, N, CUTOFF, LEVELS ) > 0, true, 'problem recurses' );
	for ( i = 0; i < ops.length; i++ ) {
		for ( j = 0; j < betas.length; j++ ) {
			ref = new Float64Array( C );
			out = new Float64Array( C );
			dgemm( realOp( ops[ i ][ 0 ] ), realOp( ops[ i ][ 1 ] ), N, N, N, 2.0, A, N, 1, 0, B, N, 1, 0, betas[ j ], ref, N, 1, 0 );
			base( ops[ i ][ 0 ], ops[ i ][ 1 ], N, N, N, 2.0, A, N, 1, 0, B, N, 1, 0, betas[ j ], out, N, 1, 0, CUTOFF, LEVELS );
			t.strictEqual( firstDifference( ref, out, betas[ j ] === 0.0 ), -1, 'returns expected value (' + ops[ i ].join( ', ' ) + ', β=' + betas[ j ] + ')' );
		}
	}
	t.end();
});
